<?php
namespace App\Tests\Runtime;
use App\Runtime\{RuntimeContainerAudit,RuntimeContainerAllocationAudit};
use PHPUnit\Framework\TestCase;
final class RuntimeContainerAllocationAuditTest extends TestCase {
 public static function definition():array{return ['entityCode'=>'container_alocacao_progress','primaryKey'=>'container_id','apiBinding'=>['sourceCode'=>'motor_progress_container_alocacao'],'apiSource'=>['responseContract'=>'sursum-programs']];}
 public static function endpoint():array{return ['method'=>'POST','url'=>'http://127.0.0.1:19910/med/web/SursumPrograms/containers-itens','requestContextFields'=>['container_id'],'bodyTemplate'=>['resource'=>'container-alocacoes','operation'=>'allocate']];}
 public static function row(string $r,array $values=[]):array {$schema=(new \ReflectionClass(RuntimeContainerAudit::class))->getConstant('SCHEMAS')[$r];$row=['container_id'=>17];foreach($schema['fields']as$type=>$fields)foreach(explode(',',$fields)as$f)$row[$f]=null;return array_replace($row,['container_id'=>17],$values);}
 public static function body():array{$before=self::row('containers',['container_id'=>17,'log_versao_custo_desatualizada'=>false]);$after=$before;$after['log_versao_custo_desatualizada']=true;$item=self::row('itens_container',['item_container_id'=>51,'item_proc_compra_id'=>11,'qt_alocada'=>40]);return ['success'=>true,'committed'=>true,'allocated'=>[$item],'skipped'=>[12],'data'=>['type'=>'message','message'=>'Confirmado'],'audit'=>['version'=>1,'source'=>'progress-transaction','resource'=>'container-alocacoes','operation'=>'allocate','recordId'=>17,'container_id'=>17,'actor'=>['login'=>'real'],'before'=>$before,'after'=>$after,'changes'=>[['resource'=>'itens_container','operation'=>'create','recordId'=>51,'before'=>[],'after'=>$item]],'warnings'=>[]]];}
 private function inspect(array $b,?array $d=null,?array $e=null,array $ids=[11,12],string $actor='real'):array{return RuntimeContainerAllocationAudit::inspect($d??self::definition(),$e??self::endpoint(),$b,['container_id'=>17],$ids,$actor);}
 public function testCommittedPhysicalAllocationAndSkippedPartitionHaveClosedProof():void{$r=$this->inspect(self::body());self::assertTrue($r['metadata']['available']);self::assertSame(17,$r['metadata']['containerId']);self::assertSame('allocate',$r['metadata']['operation']);self::assertCount(1,$r['events']);self::assertSame(11,$r['events'][0]['metadata']['itemProcCompraId']);self::assertSame(40,$r['events'][0]['after']['qt_alocada']);}
 public function testCommitActorSelectedIdsAndFullImagesCannotBeForged():void{foreach(['commit','actor','selected','partial','parent','extraItem','duplicate','overlap','quantity']as$case){$b=self::body();switch($case){case'commit':unset($b['committed']);break;case'actor':$b['audit']['actor']['login']='fake';break;case'selected':$b['allocated'][0]['item_proc_compra_id']=99;break;case'partial':unset($b['audit']['before']['num_pedido']);break;case'parent':$b['audit']['after']['container_id']=18;break;case'extraItem':$b['audit']['changes'][]=$b['audit']['changes'][0];break;case'duplicate':$b['skipped']=[12,12];break;case'overlap':$b['skipped']=[11,12];break;case'quantity':$b['audit']['changes'][0]['after']['qt_alocada']=0;break;}self::assertFalse($this->inspect($b)['metadata']['available'],$case);}}
 public function testBindingCannotChangeRouteSourceResourceOrOperation():void{foreach(['source','route','operation','context']as$case){$d=self::definition();$e=self::endpoint();switch($case){case'source':$d['apiBinding']['sourceCode']='other';break;case'route':$e['url']='https://evil.example/SursumPrograms/containers-itens';break;case'operation':$e['bodyTemplate']['operation']='delete';break;case'context':$e['requestContextFields']=[];break;}self::assertFalse($this->inspect(self::body(),$d,$e)['metadata']['available']);}}
 public function testFinancialEffectsOnlyHavePhysicalImagesAndExistingMovementPolicy():void{$b=self::body();$ledger=self::row('cta_corren_fornec_imp',['cta_corren_fornec_imp_id'=>300,'item_proc_compra_id'=>11,'item_container_id'=>51,'fornecedor_id'=>10,'cod_tipo_movto'=>5,'login'=>'real','vl_lancto'=>4]);$b['audit']['changes'][]=['resource'=>'cta_corren_fornec_imp','operation'=>'create','recordId'=>300,'before'=>[],'after'=>$ledger];self::assertTrue($this->inspect($b)['metadata']['available']);$b['audit']['changes'][1]['after']['login']='fake';self::assertFalse($this->inspect($b)['metadata']['available']);}
}
